let wvAudioContext=null;async function unlockWestVillAudio(){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;if(!wvAudioContext)wvAudioContext=new C();if(wvAudioContext.state==='suspended')await wvAudioContext.resume();}catch(e){console.warn('Audio WEST-VILL:',e);}}function playWestVillChime(){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;if(!wvAudioContext)wvAudioContext=new C();const ctx=wvAudioContext;const schedule=()=>{const now=ctx.currentTime;[[660,0,.24],[880,.2,.25],[1100,.42,.27],[1320,.66,.34]].forEach(([hz,delay,duration])=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='triangle';osc.frequency.setValueAtTime(hz,now+delay);gain.gain.setValueAtTime(.0001,now+delay);gain.gain.exponentialRampToValueAtTime(.42,now+delay+.025);gain.gain.exponentialRampToValueAtTime(.0001,now+delay+duration);osc.connect(gain);gain.connect(ctx.destination);osc.start(now+delay);osc.stop(now+delay+duration+.04);});};if(ctx.state==='suspended')ctx.resume().then(schedule).catch(e=>console.warn('Sonido WEST-VILL:',e));else schedule();}catch(e){console.warn('Sonido WEST-VILL:',e);}}document.addEventListener('pointerdown',unlockWestVillAudio,{once:true,passive:true});window.wvPlayChime=playWestVillChime;
function startDriverNotificationFeed(){if(notificationChannel){sb.removeChannel(notificationChannel);notificationChannel=null;}if(messageChannel){sb.removeChannel(messageChannel);messageChannel=null;}if(requestChannel){sb.removeChannel(requestChannel);requestChannel=null;}if(incomeChannel){sb.removeChannel(incomeChannel);incomeChannel=null;}if(expenseChannel){sb.removeChannel(expenseChannel);expenseChannel=null;}if(!['conductor','pasajero'].includes(profile?.role))return;if(profile.role==='pasajero'){requestChannel=sb.channel('westvill-requests-'+profile.id).on('postgres_changes',{event:'UPDATE',schema:'public',table:'westvill_requests',filter:'passenger_id=eq.'+profile.id},()=>{if(['viajes','solicitudes','abonos'].includes(activeTab))clientTab(activeTab);}).subscribe();}notificationChannel=sb.channel('westvill-notices-'+profile.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'westvill_notifications',filter:'user_id=eq.'+profile.id},payload=>{const n=payload.new||{};playWestVillChime();if(n.kind==='quote_ready'&&profile.role==='pasajero'){clientTab('solicitudes');}else if(['inicio','viajes','solicitudes'].includes(activeTab)){clientTab(activeTab);}else if(activeTab==='mensajes'&&profile.role==='pasajero'&&chatTargetRole==='admin'){loadThread();}alert((n.title||'Nuevo aviso')+'\\n'+(n.body||'Tenés una novedad de administración.'));}).subscribe();messageChannel=sb.channel('westvill-messages-'+profile.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'westvill_messages'},payload=>{const m=payload.new||{};if(m.recipient_id===profile.id){playWestVillChime();if(activeTab==='mensajes')loadThread();}}).subscribe();if(profile.role==='conductor'){incomeChannel=sb.channel('westvill-income-'+profile.id).on('postgres_changes',{event:'*',schema:'public',table:'westvill_income',filter:'driver_id=eq.'+profile.id},()=>{refreshClientWallet();if(['ingresos','balance'].includes(activeTab))clientTab(activeTab);}).subscribe();expenseChannel=sb.channel('westvill-expenses-'+profile.id).on('postgres_changes',{event:'*',schema:'public',table:'westvill_expenses',filter:'created_by=eq.'+profile.id},()=>{refreshClientWallet();if(['gastos','balance'].includes(activeTab))clientTab(activeTab);}).subscribe();}}
