async function activateDriverPush(){
 const button=$('#wv-push-enable'),status=$('#wv-push-status');if(!button||!status)return;
 if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window)){status.textContent='Este teléfono o navegador no admite alertas push. Usá WEST-VILL instalada desde Chrome.';return;}
 button.disabled=true;status.textContent='Activando notificaciones…';
 try{
  const permission=Notification.permission==='default'?await Notification.requestPermission():Notification.permission;
  if(permission!=='granted')throw new Error('Habilitá los permisos de notificación de WEST-VILL en Android.');
  const registration=await navigator.serviceWorker.ready;
  const existing=await registration.pushManager.getSubscription();
  const subscription=existing||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:(()=>{const v=WV_PUSH_PUBLIC_KEY.replace(/-/g,'+').replace(/_/g,'/');const bin=atob(v.padEnd(Math.ceil(v.length/4)*4,'='));return Uint8Array.from(bin,c=>c.charCodeAt(0));})()});
  const raw=subscription.toJSON();
  const {error}=await sb.from('westvill_push_subscriptions').upsert({user_id:profile.id,endpoint:raw.endpoint,p256dh:raw.keys?.p256dh,auth:raw.keys?.auth,updated_at:new Date().toISOString()},{onConflict:'user_id,endpoint'});
  if(error)throw error;
  status.textContent='¡Listo! Este teléfono recibirá avisos de WEST-VILL aunque la aplicación esté cerrada.';
  button.textContent='ALERTAS ACTIVADAS';
 }catch(e){status.textContent='No se pudieron activar: '+(e.message||String(e));button.textContent='REINTENTAR ACTIVACIÓN';}
 finally{if(button.textContent!=='ALERTAS ACTIVADAS')button.disabled=false;}
}
