 page.innerHTML=panel('Abonos escolares','<p class="client-muted">Marcá las fechas. Cada fecha exige completar nuevamente el lugar de salida y el lugar de destino. Los datos de viajes anteriores no se reutilizan. Nada se envía hasta tocar el botón de envío.</p>'+packageSummary+'<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin:14px 0"><button class="btn secondary" id="school-prev" type="button">‹</button><b style="text-transform:capitalize;color:var(--text)">'+esc(monthName)+'</b><button class="btn secondary" id="school-next" type="button">›</button></div><div style="display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px;text-align:center;margin-bottom:6px;color:var(--muted);font-size:12px;font-weight:800"><span>L</span><span>M</span><span>X</span><span>J</span><span>V</span><span>S</span><span>D</span></div><div style="display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px">'+cells.join('')+'</div><p class="client-muted" style="margin-top:12px">Azul: seleccionado. Verde: ya reservado. Tocá nuevamente un día azul para desmarcarlo.</p><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:12px">'+(editing?'<button class="btn" id="school-send" type="button">GUARDAR CAMBIOS</button><button class="btn secondary" id="school-cancel-edit" type="button">CANCELAR EDICIÓN</button>':'<button class="btn" id="school-send" type="button">ENVIAR SOLICITUD DE VIAJE</button>')+'</div>')+panel('Mis solicitudes de abono',requestList||'<p class="client-muted">Todavía no enviaste fechas. Elegí los días en el calendario y pulsá ENVIAR SOLICITUD DE VIAJE.</p>')+panel('Mis abonos anteriores',allPasses.length?allPasses.map(p=>'<article class="client-row"><b>ABONO ESCOLAR · $64.000</b><div class="client-muted">'+esc(p.origin)+' → '+esc(p.destination)+'</div><div class="client-muted">'+(counts[p.id]||0)+' de 8 viajes enviados · '+(p.payment_status==='pagado'?'PAGO REGISTRADO':'PAGO A COORDINAR')+'</div></article>').join(''):'<p class="client-muted">Todavía no tenés abonos escolares.</p>');
