async function loadThread(){const log=$('#chat-log');if(!log||!chatTarget){if(log)log.textContent='Elegí un contacto para ver la conversación.';return;}const filter='and(sender_id.eq.'+profile.id+',recipient_id.eq.'+chatTarget+'),and(sender_id.eq.'+chatTarget+',recipient_id.eq.'+profile.id+')';const {data,error:err}=await sb.from('westvill_messages').select('*').or(filter).order('created_at',{ascending:true}).limit(100);if(err){log.textContent='No se pudo cargar el chat: '+err.message;return;}const stream=(data||[]).map(m=>({date:m.created_at,html:'<div class="chat-bubble '+(m.sender_id===profile.id?'mine':'theirs')+'">'+esc(m.body)+'<div class="chat-message-time">'+new Date(m.created_at).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})+'</div></div>'}));if(['pasajero','conductor'].includes(profile.role)&&chatTargetRole==='admin'){const {data:notices,error:noticeError}=await sb.from('westvill_notifications').select('id,title,body,trip_id,created_at').eq('user_id',profile.id).order('created_at',{ascending:true}).limit(100);if(noticeError){log.textContent='No se pudieron cargar los avisos de administración: '+noticeError.message;return;}if(profile.role==='conductor'){
   const grouped=new Map();(notices||[]).forEach(n=>{const key=n.trip_id||('notice-'+n.id);if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push(n);});
   const {data:driverTrips}=await sb.from('westvill_trips').select('id,origin,destination').eq('driver_id',profile.id);
   const tripMap=new Map((driverTrips||[]).map(t=>[t.id,t]));
   grouped.forEach(items=>{items.sort((a,b)=>Date.parse(a.created_at)-Date.parse(b.created_at));const latest=items[items.length-1],trip=latest.trip_id?tripMap.get(latest.trip_id):null;const heading=trip?esc(trip.origin)+' → '+esc(trip.destination):'Avisos de Administración';const details=items.map(n=>'<div style="margin-top:5px"><b>'+esc(n.title||'Actualización')+'</b>'+(n.body?': '+esc(n.body):'')+'</div>').join('');stream.push({date:latest.created_at,html:'<div class="chat-bubble theirs"><b>ADMINISTRACIÓN · AVISOS</b><div><b>'+heading+'</b></div>'+details+'<div class="chat-message-time">'+new Date(latest.created_at).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})+'</div></div>'});});
  }else{(notices||[]).forEach(n=>stream.push({date:n.created_at,html:'<div class="chat-bubble theirs"><b>ADMINISTRACIÓN · AVISO</b><br>'+esc(n.title)+'<br>'+esc(n.body)+'<div class="chat-message-time">'+new Date(n.created_at).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})+'</div></div>'}));}}stream.sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));let lastDay='';log.innerHTML=stream.map(item=>{const date=new Date(item.date),dayKey=date.toLocaleDateString('en-CA'),dayLabel=dayKey===new Date().toLocaleDateString('en-CA')?'HOY':dayKey===new Date(Date.now()-86400000).toLocaleDateString('en-CA')?'AYER':date.toLocaleDateString('es-AR',{day:'numeric',month:'long',year:'numeric'});const divider=dayKey!==lastDay?'<div class="chat-day-divider"><span>'+dayLabel+'</span></div>':'';lastDay=dayKey;return divider+item.html;}).join('')||'<div class="chat-empty">Todavía no hay mensajes. Empezá la conversación.</div>';log.scrollTop=log.scrollHeight;}
async function start(){const isAdminRoute=new URLSearchParams(location.search).get('admin')==='1';if(isAdminRoute){role='admin';mode='login';}drawAuth();const {data:{session}}=await sb.auth.getSession();if(session){const {data:p}=await sb.from('westvill_profiles').select('id,username,display_name,role,is_available').eq('id',session.user.id).maybeSingle();if(p){profile=p;enterApp();}else await sb.auth.signOut();}}
document.addEventListener('DOMContentLoaded',start);
